    top_z = -12.386
    FRAMES = {'bottom_outer': (outer_bottom_tilt, outer_bottom_z), 'bottom_inner': (inner_bottom_tilt, inner_bottom_z), 'blend_outer': (blend_tilt, outer_blend_z), 'blend_inner': (blend_tilt, inner_blend_z), 'level': (0.0, 0.0)}
    
    def section_wire(frame, h, pts):
        tilt, z0 = FRAMES[frame]
        import math
        t = math.radians(tilt)
        ey = cq.Vector(0, math.cos(t), math.sin(t))
        ez = cq.Vector(0, -math.sin(t), math.cos(t))
        o = cq.Vector(origin_x, origin_y, z0)
        vs = [o + cq.Vector(u, 0, 0) + ey * v + ez * h for u, v in pts]
        return cq.Wire.assembleEdges([cq.Edge.makeSpline(vs, periodic=True)])
    
    def sewn_cup(outer, inner):
        wo = [section_wire(*s) for s in outer]
        wi = [section_wire(*s) for s in inner]
        lo, li = (cq.Solid.makeLoft(wo), cq.Solid.makeLoft(wi))
        side_faces = lambda s: [f for f in s.Faces() if f.geomType() != 'PLANE']
        bottom = lambda s: min([f for f in s.Faces() if f.geomType() == 'PLANE'], key=lambda f: f.Center().z)
        ring = cq.Face.makeFromWires(wo[-1], [wi[-1]])
        shell = cq.Shell.makeShell(side_faces(lo) + [bottom(lo)] + side_faces(li) + [bottom(li), ring])
        return cq.Solid.makeSolid(shell).fix()
